descriptor.templateCss:
:host {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  background: transparent !important;
}
* { box-sizing: border-box; }

/* ===== ESTILO 1 (Claro con paleta azul corporativa SMELPRO) ===== */
.smelpro-topbar,
.smelpro-topbar.tb-style-1 {
  --tb-accent: #168EAD;
  --tb-primary: #104C67;
  --tb-text: #4B6B7C;
  --tb-hover-bg: rgba(22, 142, 173, 0.08);
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 42px;
  padding: 0 12px;
  background: transparent !important;
  border-radius: inherit;
  font-family: Roboto, Arial, sans-serif;
  display: flex;
  align-items: stretch;
  overflow: hidden;
}

/* ===== ESTILO 2 (Oscuro) ===== */
.smelpro-topbar.tb-style-2,
.smelpro-topbar[data-theme="2"] {
  --tb-accent: #F2B705;
  --tb-primary: #FFFFFF;
  --tb-text: #B4B6BC;
  --tb-hover-bg: rgba(255, 255, 255, 0.06);
  background: transparent !important;
}

.tb-bar-inner {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.tb-bar-inner.is-right {
  flex-direction: row-reverse;
}

.tb-general-state {
  flex: 0 0 auto;
  color: var(--tb-accent, #168EAD);
  font-size: 14.5px;
  font-weight: 600;
  letter-spacing: 0.2px;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  padding: 0 2px;
  line-height: 1.2;
}

.smelpro-topbar.tb-style-2 .tb-general-state,
.smelpro-topbar[data-theme="2"] .tb-general-state {
  color: var(--tb-accent, #F2B705);
}

.tb-divider {
  flex: 0 0 auto;
  color: var(--tb-accent, #168EAD);
  font-size: 16px;
  font-weight: 600;
  line-height: 1;
  user-select: none;
  padding: 0 2px;
}

.smelpro-topbar.tb-style-2 .tb-divider,
.smelpro-topbar[data-theme="2"] .tb-divider {
  color: var(--tb-accent, #F2B705);
}

.tb-bar-inner.is-right .tb-divider {
  transform: scaleX(-1);
}

.tb-nav-list {
  display: flex;
  align-items: stretch;
  gap: 2px;
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}
.tb-nav-list::-webkit-scrollbar { display: none; }

.tb-bar-inner.is-right .tb-nav-list {
  justify-content: flex-start;
}

.tb-tab {
  appearance: none;
  -webkit-appearance: none;
  border: 0;
  background: transparent !important;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 14px;
  height: 100%;
  color: var(--tb-text, #4B6B7C);
  font-family: inherit;
  font-size: 13px;
  font-weight: 400;
  white-space: nowrap;
  cursor: pointer;
  transition: color 160ms ease, background-color 160ms ease;
  flex: 0 0 auto;
}

.smelpro-topbar.tb-style-2 .tb-tab,
.smelpro-topbar[data-theme="2"] .tb-tab {
  color: #B4B6BC;
}

.tb-tab:hover {
  color: var(--tb-primary, #104C67);
  background-color: var(--tb-hover-bg) !important;
}

.smelpro-topbar.tb-style-2 .tb-tab:hover,
.smelpro-topbar[data-theme="2"] .tb-tab:hover {
  color: #FFFFFF;
  background-color: rgba(255, 255, 255, 0.06) !important;
}

.tb-tab:focus-visible {
  outline: 2px solid var(--tb-accent);
  outline-offset: -2px;
  border-radius: 6px;
}

.tb-tab.active {
  color: var(--tb-primary, #104C67);
  font-weight: 600;
}

.smelpro-topbar.tb-style-2 .tb-tab.active,
.smelpro-topbar[data-theme="2"] .tb-tab.active {
  color: #FFFFFF;
  font-weight: 600;
}

.tb-indicator {
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 0;
  height: 3px;
  border-radius: 3px 3px 0 0;
  background: var(--tb-accent, #168EAD);
  transform: scaleX(0);
  opacity: 0;
  transition: transform 200ms cubic-bezier(.2,.75,.3,1), opacity 160ms ease;
}

.tb-tab.active .tb-indicator {
  transform: scaleX(1);
  opacity: 1;
}

@media(prefers-reduced-motion:reduce) {
  .tb-tab, .tb-indicator { transition: none !important; }
}

descriptor.controllerScript:
/* SMELPRO - Barra de navegación superior compacta */
var tbNav = { timer: null, dead: false, lastState: null };

function tbCtrl() {
  return self.ctx.stateController || (self.ctx.$scope && self.ctx.$scope.ctx && self.ctx.$scope.ctx.stateController);
}

function tbState() {
  try {
    var c = tbCtrl();
    return c && c.getStateId ? String(c.getStateId() || 'default') : 'default';
  } catch (e) {
    return 'default';
  }
}

function tbText(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function tbSyncConfig() {
  var s = self.ctx.$scope;
  if (!s) return;
  var cfg = self.ctx.settings || {};
  var rawStyle = String(cfg.uiStyle !== undefined ? cfg.uiStyle : '1').trim().toLowerCase();
  var uiStyle = (rawStyle === '2' || rawStyle === 'dark' || rawStyle === 'oscuro') ? '2' : '1';
  var customAccent = tbText(cfg.accentColor);
  var accentColor = customAccent || (uiStyle === '2' ? '#F2B705' : '#168EAD');

  s.cfg = cfg;
  s.uiStyle = uiStyle;
  s.accentColor = accentColor;
  s.generalText = tbText(cfg.generalStateLabel);
  s.generalSide = tbText(cfg.generalStateSide) === 'right' ? 'right' : 'left';
  s.items = (Array.isArray(cfg.navItems) ? cfg.navItems : []).filter(function(x) {
    return x && tbText(x.name);
  });
}

function tbUpdate() {
  if (tbNav.dead) return;
  var scope = self.ctx.$scope;
  if (!scope) return;
  tbSyncConfig();
  var state = tbState();
  scope.currentState = state;
  tbNav.lastState = state;
  if (self.ctx.detectChanges) self.ctx.detectChanges();
}

self.onInit = function() {
  tbNav.dead = false;
  var s = self.ctx.$scope;
  if (!s) return;

  tbSyncConfig();
  s.currentState = tbState();
  tbNav.lastState = s.currentState;

  s.isActive = function(item) {
    var state = s.currentState;
    var targetId = tbText(item.stateId);
    return !!targetId && targetId === state;
  };

  s.navigate = function(item) {
    var id = tbText(item.stateId);
    var ctrl = tbCtrl();
    if (!id || !ctrl) return;
    try {
      if (typeof ctrl.updateState === 'function') ctrl.updateState(id, {}, false);
      else if (typeof ctrl.openState === 'function') ctrl.openState(id, {}, false);
      tbUpdate();
    } catch (e) {
      console.warn('[SMELPRO Topbar] No se pudo abrir estado:', id, e);
      if (self.ctx.showErrorToast) self.ctx.showErrorToast('Estado no disponible: ' + id);
    }
  };

  if (self.ctx.detectChanges) self.ctx.detectChanges();

  tbNav.timer = setInterval(function() {
    if (tbState() !== tbNav.lastState) tbUpdate();
  }, 600);
};

self.onDashboardStateChanged = function() {
  tbUpdate();
};

self.onDataUpdated = function() {
  tbUpdate();
};

self.onDestroy = function() {
  tbNav.dead = true;
  clearInterval(tbNav.timer);
};

self.typeParameters = function() {
  return {
    datasourcesOptional: true,
    dataKeysOptional: true,
    previewWidth: '800px',
    previewHeight: '52px'
  };
};
